def color_border(grid, row, col, color):
    rows, cols = len(grid), len(grid[0])
    original = grid[row][col]
    visited = set()
    border = []

    def dfs(r, c):
        visited.add((r, c))
        is_border = False
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols or grid[nr][nc] != original:
                is_border = True
            elif (nr, nc) not in visited:
                dfs(nr, nc)
        if is_border:
            border.append((r, c))

    dfs(row, col)
    for r, c in border:
        grid[r][c] = color
    return grid

